import { HOUR, MINUTE, SECOND } from './duration-types.js';

const UNITS = { h: HOUR, m: MINUTE, s: SECOND };

// Parses durations such as "1h30m" or "45s" into seconds.
export function parseDuration(text) {
  const input = text.trim();
  const parts = input.match(/\d+[hms]/g);
  if (!parts || parts.join('') !== input) {
    throw new Error(`invalid duration: ${text}`);
  }
  return parts.reduce((total, part) => total + Number(part.slice(0, -1)) * UNITS[part.at(-1)], 0);
}
